param([string]$Configuration="Release",[string]$BuildDir="build",[string]$JuceDir="",[switch]$BootstrapJuce)
$ErrorActionPreference="Stop";$r=Split-Path -Parent $PSCommandPath;$x=Get-Content (Join-Path $r "CMakeLists.txt") -Raw;$t=[regex]::Match($x,'project\(([^\s\)]+)').Groups[1].Value;$j="";if($JuceDir){$j=(Resolve-Path $JuceDir).Path}elseif($BootstrapJuce){$p=Join-Path $r "JUCE";if(!(Test-Path (Join-Path $p "CMakeLists.txt"))){git clone --depth 1 --branch 8.0.4 --recurse-submodules https://github.com/juce-framework/JUCE.git $p};$j=(Resolve-Path $p).Path};$b=Join-Path $r $BuildDir;$a=@("-S",$r,"-B",$b);if($j){$a+="-DUWDEVST_JUCE_DIR=$j"};cmake @a;if($LASTEXITCODE-ne 0){throw "CMake failed"};foreach($q in @("${t}_Standalone","${t}_VST3")){cmake --build $b --config $Configuration --target $q;if($LASTEXITCODE-ne 0){throw "Build failed: $q"}}
